fn frame(t: i32) {
    host::display::clear(0x101014);
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, host::compose::spawn_lib("lib-math"));
    }
    let h: i32 = host::display::state_get(1);
    let st: i32 = host::compose::status(h);
    if st == 0 {
        host::display::draw_string(8, 8, "MOUNTING LIB-MATH", 0xffff00, 1);
    }
    if st == 2 {
        host::display::draw_string(8, 8, "MOUNT FAILED", 0xff0000, 1);
    }
    if st == 1 {
        let mut n: i32 = t % 32;
        if n > 16 { n = 32 - n; }
        let x: i32 = host::compose::call(h, "lerp", 40, 440, n, 0);
        if host::compose::call_ok() == 0 {
            host::display::fill_rect(x, 220, 32, 32, 0x00c8ff);
            host::display::draw_string(8, 8, "LERP VIA LIBRARY", 0x00ff66, 1);
        } else {
            host::display::draw_string(8, 8, "CALL FAILED", 0xff0000, 1);
            host::display::draw_number(8, 22, host::compose::call_ok(), 0xff0000, 1);
        }
    }
    host::display::present();
}
